#include "../cache_model.hpp"
#include <cassert>
#include <iostream>
int main(){using namespace manga;PageCache c;c.budget(1024*1024,false);assert(!c.limit);c.budget(1024*1024,true);assert(!c.limit);c.budget(128ull*1024*1024,true);assert(c.limit==63*1024*1024);c.budget(2ull*1024*1024*1024,true);assert(c.limit==PageCache::maximum);c.budget(2*1024*1024,true);assert(!c.limit);c.budget(8*1024*1024,true);assert(c.limit==3*1024*1024);c.pages[0]={"https://source.test/one",262144,1};c.pages[1]={"https://source.test/two",262144,2};c.clock=2;assert(c.oldest()==0);c.touch(0);assert(c.oldest()==1);PageCache restored;assert(restored.restore(c.save()));assert(restored.used()==524288&&restored.find("https://source.test/one")==0);auto stable=restored.save();assert(!restored.restore("{\"version\":1,\"mode\":0,\"pages\":[{\"slot\":128,\"key\":\"https://a.test\",\"bytes\":100}]}"));assert(restored.save()==stable);assert(!restored.restore("{\"version\":1,\"mode\":0,\"pages\":false}"));assert(!restored.restore("{\"version\":1,\"mode\":3,\"pages\":[]}"));Book b{"one","book","copymanga","chapter"};auto key=page_cache_key(b,7);assert(valid_cache_key(key));assert(key!=page_cache_key(b,8));b.chapter="other";assert(key!=page_cache_key(b,7));PageCache larger;for(unsigned i=0;i<100;++i)larger.pages[i]={"manga:source:book:chapter:"+std::to_string(i),49152,i+1};larger.clock=100;PageCache reopened;assert(reopened.restore(larger.save()));assert(reopened.count()==100&&reopened.used()>2*1024*1024);assert(reopened.oldest()==0);reopened.touch(0);assert(reopened.oldest()==1);std::cout<<"Cache budget, LRU eviction order, persistent index and corrupt-index rejection passed\n";}
